Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
of: unittest: fix use-after-free in of_unittest_changeset()

The variable 'parent' is assigned the value of 'nchangeset' earlier in the
function, meaning both point to the same struct device_node. The call to
of_node_put(nchangeset) can decrement the reference count to zero and
free the node if there are no other holders. After that, the code still
uses 'parent' to check for the presence of a property and to read a
string property, leading to a use-after-free.

Fix this by moving the of_node_put() call after the last access to
'parent', avoiding the UAF.

Fixes: 1c668ea65506 ("of: unittest: Use of_property_present()")
Cc: stable@vger.kernel.org
Signed-off-by: Wentao Liang <vulab@iscas.ac.cn>
Link: https://patch.msgid.link/20260409022233.418103-1-vulab@iscas.ac.cn
Signed-off-by: Rob Herring (Arm) <robh@kernel.org>

Here is the root cause:
Premature release of reference to device node via of_node_put(nchangeset) while the node is still being accessed through its alias 'parent', leading to use-after-free when 'parent' is used to check for a property and read a string property after the node has been freed.

Here is the patch:

 static void __init of_unittest_changeset(void)
 {
 #ifdef CONFIG_OF_DYNAMIC
 	int ret;
 	struct property *ppadd, padd = { .name = "prop-add", .length = 1, .value = "" };
 	struct property *ppname_n1,  pname_n1  = { .name = "name", .length = 3, .value = "n1"  };
 	struct property *ppname_n2,  pname_n2  = { .name = "name", .length = 3, .value = "n2"  };
 	struct property *ppname_n21, pname_n21 = { .name = "name", .length = 3, .value = "n21" };
 	struct property *ppupdate, pupdate = { .name = "prop-update", .length = 5, .value = "abcd" };
 	struct property *ppremove;
 	struct device_node *n1, *n2, *n21, *n22, *nchangeset, *nremove, *parent, *np;
 	static const char * const str_array[] = { "str1", "str2", "str3" };
 	const u32 u32_array[] = { 1, 2, 3 };
 	struct of_changeset chgset;
 	const char *propstr = NULL;

 	n1 = __of_node_dup(NULL, "n1");
 	unittest(n1, "testcase setup failure\n");

 	n2 = __of_node_dup(NULL, "n2");
 	unittest(n2, "testcase setup failure\n");

 	n21 = __of_node_dup(NULL, "n21");
 	unittest(n21, "testcase setup failure %p\n", n21);

 	nchangeset = of_find_node_by_path("/testcase-data/changeset");
 	nremove = of_get_child_by_name(nchangeset, "node-remove");
 	unittest(nremove, "testcase setup failure\n");

 	ppadd = __of_prop_dup(&padd, GFP_KERNEL);
 	unittest(ppadd, "testcase setup failure\n");

 	ppname_n1  = __of_prop_dup(&pname_n1, GFP_KERNEL);
 	unittest(ppname_n1, "testcase setup failure\n");

 	ppname_n2  = __of_prop_dup(&pname_n2, GFP_KERNEL);
 	unittest(ppname_n2, "testcase setup failure\n");

 	ppname_n21 = __of_prop_dup(&pname_n21, GFP_KERNEL);
 	unittest(ppname_n21, "testcase setup failure\n");

 	ppupdate = __of_prop_dup(&pupdate, GFP_KERNEL);
 	unittest(ppupdate, "testcase setup failure\n");

 	parent = nchangeset;
 	n1->parent = parent;
 	n2->parent = parent;
 	n21->parent = n2;

 	ppremove = of_find_property(parent, "prop-remove", NULL);
 	unittest(ppremove, "failed to find removal prop");

 	of_changeset_init(&chgset);

 	unittest(!of_changeset_attach_node(&chgset, n1), "fail attach n1\n");
 	unittest(!of_changeset_add_property(&chgset, n1, ppname_n1), "fail add prop name\n");

 	unittest(!of_changeset_attach_node(&chgset, n2), "fail attach n2\n");
 	unittest(!of_changeset_add_property(&chgset, n2, ppname_n2), "fail add prop name\n");

 	unittest(!of_changeset_detach_node(&chgset, nremove), "fail remove node\n");
 	unittest(!of_changeset_add_property(&chgset, n21, ppname_n21), "fail add prop name\n");

 	unittest(!of_changeset_attach_node(&chgset, n21), "fail attach n21\n");

 	unittest(!of_changeset_add_property(&chgset, parent, ppadd), "fail add prop prop-add\n");
 	unittest(!of_changeset_update_property(&chgset, parent, ppupdate), "fail update prop\n");
 	unittest(!of_changeset_remove_property(&chgset, parent, ppremove), "fail remove prop\n");
 	n22 = of_changeset_create_node(&chgset, n2, "n22");
 	unittest(n22, "fail create n22\n");
 	unittest(!of_changeset_add_prop_string(&chgset, n22, "prop-str", "abcd"),
 		 "fail add prop prop-str");
 	unittest(!of_changeset_add_prop_string_array(&chgset, n22, "prop-str-array",
 						     (const char **)str_array,
 						     ARRAY_SIZE(str_array)),
 		 "fail add prop prop-str-array");
 	unittest(!of_changeset_add_prop_u32_array(&chgset, n22, "prop-u32-array",
 						  u32_array, ARRAY_SIZE(u32_array)),
 		 "fail add prop prop-u32-array");

 	unittest(!of_changeset_apply(&chgset), "apply failed\n");

-	of_node_put(nchangeset);
-
 	/* Make sure node names are constructed correctly */
 	unittest((np = of_find_node_by_path("/testcase-data/changeset/n2/n21")),
 		 "'%pOF' not added\n", n21);
 	of_node_put(np);
 	unittest((np = of_find_node_by_path("/testcase-data/changeset/n2/n22")),
 		 "'%pOF' not added\n", n22);
 	of_node_put(np);

 	unittest(!of_changeset_revert(&chgset), "revert failed\n");

 	unittest(!of_find_node_by_path("/testcase-data/changeset/n2/n21"),
 		 "'%pOF' still present after revert\n", n21);

 	unittest(of_property_present(parent, "prop-remove"),
 		 "failed to find removed prop after revert\n");

 	ret = of_property_read_string(parent, "prop-update", &propstr);
 	unittest(!ret, "failed to find updated prop after revert\n");
 	if (!ret)
 		unittest(strcmp(propstr, "hello") == 0, "original value not in updated property after revert");

+	of_node_put(nchangeset);
 	of_changeset_destroy(&chgset);

 	of_node_put(n1);
 	of_node_put(n2);
 	of_node_put(n21);
 	of_node_put(n22);
 #endif
 }



